<?php include '../auth/cek_login.php';include '../koneksi.php';$id=(int)($_GET['id']??0);$t=mysqli_fetch_assoc(mysqli_query($conn,"SELECT t.*,m.id id_mobil,m.merk,m.tipe,m.nomor_polisi FROM transaksi t JOIN mobil m ON t.id_mobil=m.id WHERE t.id=$id AND t.status='Disewa'"));if(!$t)die('Transaksi tidak ditemukan.');if(isset($_POST['proses'])){$tgl=$_POST['tanggal_kembali'];$a=new DateTime($tgl);$b=new DateTime($t['tanggal_rencana_kembali']);$telat=($a>$b)?$b->diff($a)->days:0;$denda=$telat*100000;$s=mysqli_prepare($conn,'INSERT INTO pengembalian(id_transaksi,tanggal_kembali,keterlambatan,denda,catatan) VALUES(?,?,?,?,?)');mysqli_stmt_bind_param($s,'isiss',$id,$tgl,$telat,$denda,$_POST['catatan']);mysqli_stmt_execute($s);mysqli_query($conn,"UPDATE transaksi SET status='Dikembalikan',total_harga=total_harga+$denda WHERE id=$id");mysqli_query($conn,"UPDATE mobil SET status='Tersedia' WHERE id=".$t['id_mobil']);header('Location: index.php');exit;}?><!doctype html><html><head><link rel="stylesheet" href="../assets/style.css"></head><body><div class="content form-page"><h1>Pengembalian</h1><p>Mobil: <?=$t['merk']?> <?=$t['tipe']?> - <?=$t['nomor_polisi']?></p><form method="post"><label>Tanggal Kembali</label><input type="date" name="tanggal_kembali" value="<?=date('Y-m-d')?>" required><label>Catatan</label><textarea name="catatan"></textarea><button name="proses">Proses</button></form><p class="small">Denda Rp100.000/hari keterlambatan.</p></div></body></html>
